BEGIN;
SET LOCAL search_path = public, extensions;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(11);
INSERT INTO auth.users(id,email) VALUES('a0699999-1111-4111-8111-111111111111','profile-permissions@kipu.test');
SELECT set_config('request.jwt.claims','{"sub":"a0699999-1111-4111-8111-111111111111","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.ensure_profile()$$,'authenticated bootstraps profile with deletion guards installed');
SELECT is(public.update_profile_preferences('a0699999-1111-4111-8111-111111111112',1,'{"display_name":"Fixture","hide_balances":true}'::jsonb)->>'result','APPLIED','authenticated preference RPC applies under dedicated executor');
SELECT is(public.update_profile_preferences('a0699999-1111-4111-8111-111111111112',1,'{"display_name":"Fixture","hide_balances":true}'::jsonb)->>'result','DUPLICATE','same operation replays safely');
SELECT is(public.update_profile_preferences('a0699999-1111-4111-8111-111111111113',1,'{"hide_balances":false}'::jsonb)->>'result','CONFLICT','stale revision remains a conflict');
SELECT is((SELECT revision FROM public.profiles WHERE user_id=auth.uid()),2::bigint,'duplicate and conflict do not increment revision');
SELECT ok(NOT has_schema_privilege('authenticated','private','USAGE'),'clients still cannot resolve private schema');
RESET ROLE;
SELECT ok(NOT has_table_privilege('authenticated','private.profile_preference_receipts','SELECT'),'receipt payloads remain private');
SELECT ok(NOT has_table_privilege('profile_preferences_executor','private.account_deletion_requests','SELECT'),'profile executor has no deletion capability');
SELECT ok(NOT has_schema_privilege('profile_preferences_executor','auth','USAGE') AND NOT has_schema_privilege('profile_bootstrap_executor','auth','USAGE'),'executors work without access to auth schema');
SELECT ok(NOT has_function_privilege('authenticated','private.profile_session_uid()','EXECUTE'),'clients cannot call the private subject helper');
SELECT ok((SELECT prosecdef AND proowner='postgres'::regrole AND proconfig @> ARRAY['search_path=""'] FROM pg_proc WHERE oid='private.profile_session_uid()'::regprocedure),'helper has fixed search path and minimal postgres-owned body');
SELECT * FROM finish();
ROLLBACK;
